// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    PoCGame c;

    receive() external payable {}

    function setUp() public { c = new PoCGame(address(this), 0); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(this));
        amount = bound(amount, 0, 1 ether);

        vm.prank(address(this));
        c.OpenToThePublic();

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.donate{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok, "after OpenToThePublic, anyone may donate");
    }
}
